using System.Globalization;

namespace MediaServer.Api.Hls;

/// <summary>
/// Builds the ffmpeg argument vector. Pure: returns discrete arguments (never a shell string), and the input path
/// always follows "-i" so a file name beginning with "-" can't be read as an option.
/// </summary>
public static class HlsCommandBuilder
{
    public const string PlaylistName = "index.m3u8";
    public const string InitName = "init.mp4";
    /// <summary>ffmpeg's own (unused) playlist in segmented mode; the served index.m3u8 is generated by the server.</summary>
    public const string RunPlaylistName = "ffmpeg.m3u8";

    private static string Num(double v) => v.ToString("0.###", CultureInfo.InvariantCulture);

    /// <summary>
    /// AAC encoders start with 1024 samples of priming, which makes the first audio timestamp negative; the MPEG-TS muxer then shifts
    /// a run that starts at 0 forward by that much, but not a run that starts mid-file (its offset keeps everything positive).
    /// Applying the same constant to every segmented run, with audio fixed at 48 kHz so the constant is known, makes runs started
    /// by different seeks line up exactly (verified: video frames stay on a 40 ms grid across the seam).
    /// </summary>
    private const int SegmentedSampleRate = 48000;
    private const double AudioPrimingSeconds = 1024.0 / SegmentedSampleRate;

    /// <param name="startIndex">First segment this run produces (segmented transcodes only; the run begins at startIndex × SegmentSeconds).</param>
    public static List<string> Build(string inputPath, string outputDir, HlsPlan plan, HlsOptions o, int startIndex = 0, bool resume = false)
    {
        var seg = plan.Live ? o.LiveSegmentSeconds : o.SegmentSeconds;
        var startSeconds = plan.Vod ? startIndex * (double)seg : 0;
        var a = new List<string> { "-nostdin", "-hide_banner", "-loglevel", "error", "-y" };
        if (startSeconds > 0) a.AddRange(["-ss", Num(startSeconds)]);   // input seek: fast, and frame-accurate when re-encoding
        // Network input: only http(s) transports, give up on stalls, ride out brief drops, tolerate the odd corrupt packet.
        if (plan.Live)
            a.AddRange(["-protocol_whitelist", "http,https,tcp,tls,crypto", "-rw_timeout", "15000000", "-reconnect", "1", "-reconnect_streamed", "1",
                        "-reconnect_delay_max", "5", "-fflags", "+genpts+discardcorrupt", "-analyzeduration", "3000000", "-probesize", "3000000"]);
        a.AddRange(["-i", inputPath]);

        // Burning in subtitles: the picture and the chosen subtitle stream go through one filter graph; the result is what gets encoded.
        var burn = plan.Video == VideoMode.Encode && plan.BurnSubtitle is not null;
        a.AddRange(["-map", burn ? "[v]" : $"0:{plan.VideoStream}"]);
        if (plan.AudioStream is { } audio) a.AddRange(["-map", $"0:{audio}"]);
        a.AddRange(burn ? ["-dn"] : ["-sn", "-dn"]);
        a.AddRange(["-map_metadata", "-1", "-max_muxing_queue_size", "1024"]);

        if (plan.Video == VideoMode.Copy)
        {
            a.AddRange(["-c:v", "copy"]);
            if (plan.VideoTag is { } tag) a.AddRange(["-tag:v", tag]);
        }
        else
        {
            // Keyframes on exact segment boundaries so every segment starts cleanly (and a restart can begin at any of them).
            var keyframes = $"expr:gte(t,n_forced*{seg})";
            // Downscale only, never upscale. The escaped comma is ffmpeg filtergraph syntax.
            var scale = plan.MaxWidth is { } w ? $"scale=min({w}\\,iw):-2" : $"scale=-2:min({o.MaxHeight}\\,ih)";
            var chain = plan.Deinterlace ? "yadif=0:-1:1," + scale : scale;          // yadif: only frames flagged interlaced are touched
            if (burn) a.AddRange(["-filter_complex", $"[0:{plan.VideoStream}][0:{plan.BurnSubtitle}]overlay=eof_action=pass:repeatlast=0,{chain}[v]"]);
            else a.AddRange(["-vf", chain]);
            var rate = plan.VideoKbps is { } kbps ? new[] { "-maxrate", $"{kbps}k", "-bufsize", $"{kbps * 2}k" } : [];
            // B-frames delay presentation vs decode timestamps by a run-dependent amount, which would misalign runs started by seeks.
            string[] noB = plan.Vod ? ["-bf", "0"] : [];
            if (o.Encoder == "nvenc")
                a.AddRange(["-c:v", "h264_nvenc", "-preset", "p4", "-rc", "vbr", "-cq", plan.VideoKbps is null ? "23" : "28", "-b:v", "0",
                            "-pix_fmt", "yuv420p", "-profile:v", "high", "-forced-idr", "1", "-force_key_frames", keyframes, .. noB, .. rate]);
            else
                a.AddRange(["-c:v", "libx264", "-preset", o.Preset, "-crf", (plan.VideoKbps is null ? o.Crf : o.Crf + 2).ToString(System.Globalization.CultureInfo.InvariantCulture), "-pix_fmt", "yuv420p",
                            "-profile:v", "high", "-level", "4.1", "-sc_threshold", "0", "-force_key_frames", keyframes, .. noB, .. rate]);
        }

        switch (plan.Audio)
        {
            case AudioMode.Copy: a.AddRange(["-c:a", "copy"]); break;
            case AudioMode.Aac:
                a.AddRange(["-c:a", "aac", "-b:a", $"{plan.AudioKbps}k", "-ac", "2"]);
                if (plan.Vod) a.AddRange(["-ar", SegmentedSampleRate.ToString(CultureInfo.InvariantCulture)]);
                break;
            case AudioMode.None: a.Add("-an"); break;
        }

        var fmp4 = plan.Segments == HlsSegments.Fmp4;
        a.AddRange(["-f", "hls", "-hls_time", seg.ToString(CultureInfo.InvariantCulture)]);
        if (plan.Vod)
        {
            // Segmented mode: segment N always covers [N×seg, (N+1)×seg) of the source and carries those timestamps, so the
            // pieces from separate runs (after a seek) line up on one timeline.
            a.AddRange(["-output_ts_offset", (startSeconds + AudioPrimingSeconds).ToString("0.######", CultureInfo.InvariantCulture), "-muxdelay", "0", "-start_number", startIndex.ToString(CultureInfo.InvariantCulture),
                        "-hls_list_size", "4"]);
        }
        else if (plan.Live)
        {
            // Live: a sliding window (about a minute of rewind). Old segments are deleted so a long session doesn't fill the disk.
            a.AddRange(["-hls_list_size", "30", "-hls_delete_threshold", "4"]);
        }
        else
        {
            // EVENT playlist: grows as segments finish and gains ENDLIST when done, so playback starts immediately.
            a.AddRange(["-hls_list_size", "0", "-hls_playlist_type", "event"]);
        }
        // A reconnect continues the same playlist (numbering carries on) and marks the seam so the player resynchronises.
        var flags = plan.Live ? "delete_segments+independent_segments+temp_file" + (resume ? "+append_list+discont_start" : "") : "independent_segments+temp_file";
        a.AddRange(["-hls_segment_type", fmp4 ? "fmp4" : "mpegts", "-hls_flags", flags]);
        if (fmp4) a.AddRange(["-hls_fmp4_init_filename", InitName]);
        a.AddRange(["-hls_segment_filename", Path.Combine(outputDir, fmp4 ? "seg%05d.m4s" : "seg%05d.ts"),
                    Path.Combine(outputDir, plan.Vod ? RunPlaylistName : PlaylistName)]);
        return a;
    }

    /// <summary>The full-length VOD playlist for a segmented transcode, available before any segment exists.</summary>
    public static string BuildVodPlaylist(double durationSeconds, int segmentSeconds)
    {
        var count = SegmentCount(durationSeconds, segmentSeconds);
        var sb = new System.Text.StringBuilder();
        sb.Append("#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-PLAYLIST-TYPE:VOD\n#EXT-X-INDEPENDENT-SEGMENTS\n");
        sb.Append("#EXT-X-TARGETDURATION:").Append(segmentSeconds.ToString(CultureInfo.InvariantCulture)).Append("\n#EXT-X-MEDIA-SEQUENCE:0\n");
        for (var i = 0; i < count; i++)
        {
            var len = i < count - 1 ? segmentSeconds : durationSeconds - (count - 1) * (double)segmentSeconds;
            sb.Append("#EXTINF:").Append(len.ToString("0.000", CultureInfo.InvariantCulture)).Append(",\nseg").Append(i.ToString("00000", CultureInfo.InvariantCulture)).Append(".ts\n");
        }
        sb.Append("#EXT-X-ENDLIST\n");
        return sb.ToString();
    }

    /// <summary>
    /// A tail shorter than this is folded into the previous segment. Container durations often exceed the video's by a few
    /// milliseconds (audio runs longer); a segment covering less than one frame would be listed but never produced, and the
    /// player would hit a 404 on the very last request.
    /// </summary>
    private const double MinTailSeconds = 0.25;

    public static int SegmentCount(double durationSeconds, int segmentSeconds) =>
        Math.Max(1, (int)Math.Ceiling((durationSeconds - MinTailSeconds) / segmentSeconds));
}
